interface MeasurementControlFence { schema:1;sessionId:string;id:string;attemptId:string }
const measurementFencePath=(directory:string)=>path.join(directory,'workshop-measurement-fence.json');
const measurementFence=(value:unknown):MeasurementControlFence=>{const fence=object(value);if(fence.schema!==1||typeof fence.sessionId!=='string'||!fence.sessionId||typeof fence.id!=='string'||!fence.id||typeof fence.attemptId!=='string'||!fence.attemptId)throw new Error('Invalid durable workshop measurement fence');return fence as unknown as MeasurementControlFence;};
