async function clearMeasurementFence(directory:string,expected:MeasurementControlFence):Promise<void>{const current=await readMeasurementFence(directory);if(!current||current.sessionId!==expected.sessionId||current.id!==expected.id||current.attemptId!==expected.attemptId)throw new Error('Durable workshop measurement fence identity changed');await rm(measurementFencePath(directory));}
/** Reconcile a durable measurement hold before replacement control can mutate pause state. */
