const jsonObject=(text:string):Record<string,unknown>=>{
  const fenced=/```(?:json)?\s*([\s\S]*?)```/i.exec(text)?.[1];
  for(const candidate of [fenced,text.slice(text.indexOf('{'),text.lastIndexOf('}')+1)])try{return object(JSON.parse(candidate??''));}catch{/* try the next representation */}
  throw new Error('Managed workshop role did not return one JSON object');
};
