  const aliases:Record<string,string>={'green circuit':'electronic-circuit','green circuits':'electronic-circuit','electronic circuit':'electronic-circuit','electronic circuits':'electronic-circuit','iron gear':'iron-gear-wheel','iron gears':'iron-gear-wheel','iron gear wheel':'iron-gear-wheel','iron gear wheels':'iron-gear-wheel'};
